@namespace sv_b62cd37ead7f4ed4a44d1859d17058c3.Components.Pages.Apply

<div class="step-form">
    <h3>Work History</h3>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var entry = Entries[i];
        var index = i;
        <WorkEntryForm Index="index"
                       Company="@entry.Company"
                       Title="@entry.Title"
                       StartDate="@entry.StartDate"
                       EndDate="@entry.EndDate"
                       IsCurrent="@entry.IsCurrent"
                       Description="@entry.Description"
                       ShowRemove="@(Entries.Count > 1)"
                       OnRemove="() => RemoveEntry(index)"
                       OnChanged="HandleEntryChanged" />
    }

    <button class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(validationMessage))
    {
        <div class="validation-error">@validationMessage</div>
    }

    <div class="form-actions">
        <button class="btn-back" @onclick="OnBack">Back</button>
        <button class="btn-next" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryModel> Entries { get; set; } = new();
    [Parameter] public EventCallback<List<WorkEntryModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? validationMessage;

    protected override void OnInitialized()
    {
        if (Entries.Count == 0)
        {
            Entries.Add(new WorkEntryModel());
        }
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private void HandleEntryChanged((int Index, string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description) data)
    {
        if (data.Index < Entries.Count)
        {
            Entries[data.Index] = new WorkEntryModel
            {
                Company = data.Company,
                Title = data.Title,
                StartDate = data.StartDate,
                EndDate = data.EndDate,
                IsCurrent = data.IsCurrent,
                Description = data.Description
            };
        }
    }

    private async Task HandleNext()
    {
        validationMessage = null;
        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                validationMessage = "Company name and job title are required for each entry.";
                return;
            }
        }
        await OnNext.InvokeAsync(Entries);
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}

@namespace sv_b62cd37ead7f4ed4a44d1859d17058c3.Components.Pages.Apply

<div class="step-form">
    <h3>References</h3>
    <p class="step-description">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var reference = References[i];
        var index = i;
        <ReferenceForm Index="index"
                       Name="@reference.Name"
                       Relationship="@reference.Relationship"
                       Email="@reference.Email"
                       Phone="@reference.Phone"
                       ShowRemove="@(References.Count > 2)"
                       OnRemove="() => RemoveReference(index)"
                       OnChanged="HandleReferenceChanged" />
    }

    @if (References.Count < 3)
    {
        <button class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(validationMessage))
    {
        <div class="validation-error">@validationMessage</div>
    }

    <div class="form-actions">
        <button class="btn-back" @onclick="OnBack">Back</button>
        <button class="btn-next" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? validationMessage;

    protected override void OnInitialized()
    {
        while (References.Count < 2)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private void HandleReferenceChanged((int Index, string Name, string Relationship, string Email, string Phone) data)
    {
        if (data.Index < References.Count)
        {
            References[data.Index] = new ReferenceModel
            {
                Name = data.Name,
                Relationship = data.Relationship,
                Email = data.Email,
                Phone = data.Phone
            };
        }
    }

    private async Task HandleNext()
    {
        validationMessage = null;
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                validationMessage = "All reference fields are required.";
                return;
            }
        }
        await OnNext.InvokeAsync(References);
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

@namespace sv_b62cd37ead7f4ed4a44d1859d17058c3.Components.Pages.Apply

<div class="step-form">
    <h3>Cover Letter</h3>

    <div class="form-group">
        <label for="coverLetter">Write your cover letter</label>
        <textarea id="coverLetter" rows="12" maxlength="@MaxLength"
                  @bind="CoverLetter" @bind:event="oninput"></textarea>
        <div class="char-count @(CoverLetter.Length >= MaxLength ? "at-limit" : "")">
            @CoverLetter.Length / @MaxLength characters
        </div>
    </div>

    @if (!string.IsNullOrEmpty(validationMessage))
    {
        <div class="validation-error">@validationMessage</div>
    }

    <div class="form-actions">
        <button class="btn-back" @onclick="OnBack">Back</button>
        <button class="btn-next" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? validationMessage;

    private async Task HandleNext()
    {
        validationMessage = null;
        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            validationMessage = "Please write a cover letter.";
            return;
        }
        await OnNext.InvokeAsync(CoverLetter);
    }
}

@namespace sv_b62cd37ead7f4ed4a44d1859d17058c3.Components.Pages.Apply

<div class="step-form review-step">
    <h3>Review & Submit</h3>
    <p class="step-description">Please review your application before submitting.</p>

    <div class="review-section">
        <div class="review-header">
            <h4>Personal Information</h4>
            <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
        </div>
        <dl>
            <dt>Full Name</dt><dd>@FullName</dd>
            <dt>Email</dt><dd>@Email</dd>
            <dt>Phone</dt><dd>@Phone</dd>
            <dt>Address</dt><dd>@Address</dd>
        </dl>
    </div>

    <div class="review-section">
        <div class="review-header">
            <h4>Work History</h4>
            <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
        </div>
        @foreach (var entry in WorkEntries)
        {
            <div class="review-entry">
                <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                <br />
                <span class="date-range">
                    @entry.StartDate.ToString("MMM yyyy") &mdash;
                    @(entry.EndDate.HasValue ? entry.EndDate.Value.ToString("MMM yyyy") : "Present")
                </span>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p>@entry.Description</p>
                }
            </div>
        }
    </div>

    <div class="review-section">
        <div class="review-header">
            <h4>References</h4>
            <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
        </div>
        @foreach (var reference in References)
        {
            <div class="review-entry">
                <strong>@reference.Name</strong> (@reference.Relationship)
                <br />@reference.Email | @reference.Phone
            </div>
        }
    </div>

    <div class="review-section">
