{"file_text": "@page "/apply"
@using sv_b62cd37ead7f4ed4a44d1859d17058c3.Models
@using sv_b62cd37ead7f4ed4a44d1859d17058c3.Components.Pages.Apply
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    @if (submittedId.HasValue)
    {
        <div class="confirmation">
            <div class="confirmation-icon">&#10003;</div>
            <h2>Application Submitted!</h2>
            <p>Your application has been received. Your application ID is:</p>
            <div class="application-id">#@submittedId.Value</div>
            <p>Please save this number for your records.</p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="currentStep" CompletedSteps="completedSteps" OnStepSelected="GoToStep" />

        @switch (currentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync"
                                  OnNext="HandlePersonalInfoNext" />
                break;
            case 1:
                <WorkHistoryStep Entries="workEntries" OnNext="HandleWorkHistoryNext" OnBack="GoBack" />
                break;
            case 2:
                <ReferencesStep References="references" OnNext="HandleReferencesNext" OnBack="GoBack" />
                break;
            case 3:
                <CoverLetterStep CoverLetter="@coverLetter" OnNext="HandleCoverLetterNext" OnBack="GoBack" />
                break;
            case 4:
                <ReviewStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                            WorkEntries="workEntries" References="references" CoverLetter="@coverLetter"
                            IsSubmitting="isSubmitting" OnBack="GoBack" OnSubmit="HandleSubmit"
                            OnEditSection="GoToStep" />
                break;
        }
    }
</div>

@code {
    private int currentStep;
    private HashSet<int> completedSteps = new();
    private bool isSubmitting;
    private int? submittedId;

    // Step 1 data
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2 data
    private List<WorkHistoryStep.WorkEntryModel> workEntries = new();

    // Step 3 data
    private List<ReferencesStep.ReferenceModel> references = new();

    // Step 4 data
    private string coverLetter = "";

    private void HandlePersonalInfoNext((string FullName, string Email, string Phone, string Address) data)
    {
        fullName = data.FullName;
        email = data.Email;
        phone = data.Phone;
        address = data.Address;
        completedSteps.Add(0);
        currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkHistoryStep.WorkEntryModel> entries)
    {
        workEntries = entries;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> refs)
    {
        references = refs;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        completedSteps.Add(3);
        currentStep = 4;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;

        var application = new JobApplication(
            new PersonalInfo(fullName, email, phone, address),
            new WorkHistory(workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()),
            references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            coverLetter
        );

        submittedId = await ApplicationService.SubmitApplicationAsync(application);
        isSubmitting = false;
    }

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }
}
