+.apply-page {
+    max-width: 800px;
+    margin: 0 auto;
+    padding: 2rem;
+}
+
+.apply-page h1 {
+    text-align: center;
+    margin-bottom: 2rem;
+    color: #1a1a2e;
+}
+
+/* Step Indicator */
+.step-indicator {
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    margin-bottom: 2rem;
+    padding: 1rem 0;
+}
+
+.step {
+    display: flex;
+    flex-direction: column;
+    align-items: center;
+    cursor: default;
+    min-width: 80px;
+}
+
+.step.completed {
+    cursor: pointer;
+}
+
+.step-circle {
+    width: 36px;
+    height: 36px;
+    border-radius: 50%;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    font-weight: bold;
+    font-size: 0.9rem;
+    border: 2px solid #ccc;
+    background: #fff;
+    color: #999;
+    transition: all 0.2s;
+}
+
+.step.active .step-circle {
+    border-color: #4361ee;
+    background: #4361ee;
+    color: #fff;
+}
+
+.step.completed .step-circle {
+    border-color: #2ec4b6;
+    background: #2ec4b6;
+    color: #fff;
+}
+
+.step.dimmed .step-circle {
+    border-color: #ddd;
+    background: #f5f5f5;
+    color: #bbb;
+}
+
+.step-label {
+    margin-top: 0.5rem;
+    font-size: 0.75rem;
+    text-align: center;
+    color: #666;
+}
+
+.step.active .step-label {
+    color: #4361ee;
+    font-weight: 600;
+}
+
+.step.completed .step-label {
+    color: #2ec4b6;
+}
+
+.step.dimmed .step-label {
+    color: #bbb;
+}
+
+.step-connector {
+    flex: 1;
+    height: 2px;
+    background: #ddd;
+    margin: 0 0.5rem;
+    margin-bottom: 1.5rem;
+    max-width: 60px;
+}
+
+.step-connector.completed {
+    background: #2ec4b6;
+}
+
+/* Form Styles */
+.step-form {
+    background: #fff;
+    border: 1px solid #e0e0e0;
+    border-radius: 8px;
+    padding: 2rem;
+    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
+}
+
+.step-form h3 {
+    margin-top: 0;
+    margin-bottom: 0.5rem;
+    color: #1a1a2e;
+}
+
+.step-description {
+    color: #666;
+    margin-bottom: 1.5rem;
+}
+
+.form-group {
+    margin-bottom: 1rem;
+}
+
+.form-group label {
+    display: block;
+    margin-bottom: 0.3rem;
+    font-weight: 500;
+    color: #333;
+    font-size: 0.9rem;
+}
+
+.form-group input[type="text"],
+.form-group input[type="email"],
+.form-group input[type="tel"],
+.form-group input[type="date"],
+.form-group textarea {
+    width: 100%;
+    padding: 0.6rem 0.8rem;
+    border: 1px solid #ddd;
+    border-radius: 4px;
+    font-size: 0.95rem;
+    transition: border-color 0.2s;
+    box-sizing: border-box;
+}
+
+.form-group input:focus,
+.form-group textarea:focus {
+    outline: none;
+    border-color: #4361ee;
+    box-shadow: 0 0 0 2px rgba(67, 97, 238, 0.1);
+}
+
+.form-row {
+    display: flex;
+    gap: 1rem;
+}
+
+.form-row .form-group {
+    flex: 1;
+}
+
+.checkbox-label {
+    display: inline-flex !important;
+    align-items: center;
+    gap: 0.4rem;
+    font-weight: normal !important;
+    margin-top: 0.3rem;
+    font-size: 0.85rem;
+    color: #555;
+}
+
+.checkbox-label input[type="checkbox"] {
+    width: auto;
+}
+
+/* Buttons */
+.form-actions {
+    display: flex;
+    justify-content: space-between;
+    margin-top: 1.5rem;
+    padding-top: 1.5rem;
+    border-top: 1px solid #eee;
+}
+
+.btn-next,
+.btn-submit {
+    background: #4361ee;
+    color: #fff;
+    border: none;
+    padding: 0.7rem 1.5rem;
+    border-radius: 4px;
+    font-size: 0.95rem;
+    cursor: pointer;
+    transition: background 0.2s;
+}
+
+.btn-next:hover,
+.btn-submit:hover {
+    background: #3a56d4;
+}
+
+.btn-next:disabled,
+.btn-submit:disabled {
+    background: #a0a0a0;
+    cursor: not-allowed;
+}
+
+.btn-back {
+    background: #fff;
+    color: #666;
+    border: 1px solid #ddd;
+    padding: 0.7rem 1.5rem;
+    border-radius: 4px;
+    font-size: 0.95rem;
+    cursor: pointer;
+    transition: all 0.2s;
+}
+
+.btn-back:hover {
+    border-color: #999;
+    color: #333;
+}
+
+.btn-secondary {
+    background: #fff;
+    color: #4361ee;
+    border: 1px dashed #4361ee;
+    padding: 0.5rem 1rem;
+    border-radius: 4px;
+    font-size: 0.9rem;
+    cursor: pointer;
+    margin-top: 0.5rem;
+    transition: background 0.2s;
+}
+
+.btn-secondary:hover {
+    background: #f0f4ff;
+}
+
+.btn-remove {
+    background: none;
+    color: #e63946;
+    border: none;
+    padding: 0.3rem 0.6rem;
+    font-size: 0.85rem;
+    cursor: pointer;
+}
+
+.btn-remove:hover {
+    text-decoration: underline;
+}
+
+.btn-link {
+    background: none;
+    border: none;
+    color: #4361ee;
+    cursor: pointer;
+    font-size: 0.9rem;
+    text-decoration: underline;
+}
+
+.btn-link:hover {
+    color: #3a56d4;
+}
+
+/* Validation */
+.validation-error {
+    color: #e63946;
+    background: #ffeef0;
+    border: 1px solid #fdd;
+    padding: 0.6rem 1rem;
+    border-radius: 4px;
+    margin-top: 1rem;
+    font-size: 0.9rem;
+}
+
+.field-error {
+    color: #e63946;
+    font-size: 0.8rem;
+    margin-top: 0.2rem;
+    display: block;
+}
+
+/* Character count */
+.char-count {
+    text-align: right;
+    font-size: 0.8rem;
+    color: #888;
+    margin-top: 0.3rem;
+}
+
+.char-count.at-limit {
+    color: #e63946;
+    font-weight: 600;
+}
+
+/* Work Entry / Reference Forms */
+.work-entry-form,
+.reference-form {
+    border: 1px solid #eee;
+    border-radius: 6px;
+    padding: 1.2rem;
+    margin-bottom: 1rem;
+    background: #fafafa;
+}
+
+.entry-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+}
+
+.entry-header h4,
+.reference-form h4 {
+    margin: 0 0 0.8rem 0;
+    color: #444;
+}
+
+/* Review Step */
+.review-step .review-section {
+    border: 1px solid #eee;
+    border-radius: 6px;
+    padding: 1.2rem;
+    margin-bottom: 1rem;
+}
+
+.review-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 0.8rem;
+}
+
+.review-header h4 {
+    margin: 0;
+    color: #333;
+}
+
+.review-section dl {
+    display: grid;
+    grid-template-columns: 120px 1fr;
+    gap: 0.4rem 1rem;
+    margin: 0;
+}
+
+.review-section dt {
+    font-weight: 600;
+    color: #555;
+    font-size: 0.9rem;
+}
+
+.review-section dd {
+    margin: 0;
+    color: #333;
+}
+
+.review-entry {
+    padding: 0.6rem 0;
+    border-bottom: 1px solid #f0f0f0;
+}
+
+.review-entry:last-child {
+    border-bottom: none;
+}
+
+.date-range {
+    font-size: 0.85rem;
+    color: #666;
+}
+
+.cover-letter-preview {
+    white-space: pre-wrap;
+    background: #f9f9f9;
+    padding: 0.8rem;
+    border-radius: 4px;
+    font-size: 0.9rem;
+    line-height: 1.5;
+}
+
+/* Confirmation */
+.confirmation {
+    text-align: center;
+    padding: 3rem;
+    background: #fff;
+    border: 1px solid #e0e0e0;
+    border-radius: 8px;
+    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
+}
+
+.confirmation-icon {
+    width: 60px;
+    height: 60px;
+    border-radius: 50%;
+    background: #2ec4b6;
+    color: #fff;
+    font-size: 2rem;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    margin: 0 auto 1rem;
+}
+
+.confirmation h2 {
+    color: #1a1a2e;
+    margin-bottom: 0.5rem;
+}
+
+.application-id {
+    font-size: 1.8rem;
+    font-weight: bold;
+    color: #4361ee;
+    margin: 1rem 0;
+}
+

