    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" @bind="Title" @bind:after="NotifyChanged" @bind:event="oninput" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" @bind="StartDate" @bind:after="NotifyChanged" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" @bind="EndDate" @bind:after="NotifyChanged" disabled="@IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" @bind="IsCurrent" @bind:after="HandleCurrentChanged" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" @bind="Description" @bind:after="NotifyChanged" @bind:event="oninput"></textarea>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<(int Index, string Company, string Title, DateTime? EndDate, bool IsCurrent, string Description)> OnChanged { get; set; }

    private void HandleCurrentChanged()
    {
        if (IsCurrent) EndDate = null;
        NotifyChanged();
    }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync((Index, Company, Title, EndDate, IsCurrent, Description));
    }
}

